output_text:
[
  {
    "id": "no_cart_in_handcarry_aisle",
    "text": "Carts are not allowed in single-file shelf aisles where shelves border both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelvesBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "handCarryAisle": {
          "and": [
            "singleFileAisle",
            "shelvesBothSides"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "handCarryAisle"
        ]
      }
    }
  },
  {
    "id": "enter_handcarry_without_cart",
    "text": "A customer must not enter a hand-carry-only aisle while still pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelvesBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "handCarryAisle": {
          "and": [
            "singleFileAisle",
            "shelvesBothSides"
          ]
        }
      },
      "events": {
        "enterHandCarryWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE",
              {
                "not": "handCarryAisle"
              }
            ]
          },
          "post": "handCarryAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterHandCarryWithCart"
    }
  },
  {
    "id": "park_cart_only_at_wide_mouth",
    "text": "A cart may only be released or parked at a wide non-shelf aisle mouth.",
    "abstraction": {
      "state_properties": {
        "wideAisleMouth": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "releaseCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "releaseCart",
          {
            "not": "wideAisleMouth"
          }
        ]
      }
    }
  },
  {
    "id": "reclaim_parked_cart",
    "text": "Whenever a customer parks a cart, they are obliged to reclaim it before leaving.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "releaseCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "takeCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "releaseCart",
      "discharge": "takeCart"
    }
  },
  {
    "id": "no_cart_service_in_two_sided_shelf_aisle",
    "text": "Items in two-sided shelf aisles must be handled without a cart.",
    "abstraction": {
      "state_properties": {
        "twoSidedShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "twoSidedShelfAisle",
          "hasCart",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "return_from_handcarry_aisle",
    "text": "After entering a hand-carry-only aisle without the cart, the customer must return to a wide aisle mouth.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelvesBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "handCarryAisle": {
          "and": [
            "singleFileAisle",
            "shelvesBothSides"
          ]
        },
        "wideAisleMouth": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "enterHandCarryWithoutCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE",
              {
                "not": "handCarryAisle"
              }
            ]
          },
          "post": "handCarryAisle"
        },
        "returnToMouth": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "handCarryAisle",
              "MOVE"
            ]
          },
          "post": "wideAisleMouth"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterHandCarryWithoutCart",
      "discharge": "returnToMouth"
    }
  },
  {
    "id": "no_lateral_motion_in_single_file",
    "text": "Movement inside a single-file shelf aisle should be longitudinal only, with no east-west sidestepping.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelvesBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "handCarryAisle": {
          "and": [
            "singleFileAisle",
            "shelvesBothSides"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "handCarryAisle",
          {
            "or": [
              "E",
              "W"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "cart_separation_only_in_handcarry_zone",
    "text": "After the entrance area, a customer may be without their cart only in a hand-carry aisle or its wide mouth.",
    "abstraction": {
      "state_properties": {
        "entranceOrCartBay": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelvesBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "handCarryAisle": {
          "and": [
            "singleFileAisle",
            "shelvesBothSides"
          ]
        },
        "wideAisleMouth": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        },
        "allowedCartFreeZone": {
          "or": [
            "entranceOrCartBay",
            "handCarryAisle",
            "wideAisleMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "not": "allowedCartFreeZone"
          }
        ]
      }
    }
  }
]
